import logging
from taf.ul.mobile.ui.android.factory import MobileFactory


class Harmony(object):

    """
    Harmony OS base Class
    """

    _DEFAULT_UI_VERSION = "HarmonyOS 3.0.0"

    def __init__(
        self, ui_version=None, ue_pc_ssh_config=None, ue_serial_number=None, **kwargs
    ):
        self._ui_version = ui_version or self._DEFAULT_UI_VERSION
        self._ue_pc_ssh_config = ue_pc_ssh_config
        self._ue_serial_number = ue_serial_number

        self._ue_proxy = None

    def setup(self, **kwargs):
        self._ue_proxy = MobileFactory().create(
            ui_version=self._ui_version,
            serial_number=self._ue_serial_number,
            **self._ue_pc_ssh_config
        )

        self._ue_proxy.setup()

    def teardown(self):
        self._ue_proxy.teardown()

    def attach(self):
        self._ue_proxy.unlock_screen()
        self._ue_proxy.disable_airplane()
        self._ue_proxy.enable_mobile_data()

    def get_ue_ip(self):
        ue_ip = self._ue_proxy.get_ue_ip()
        logging.info("get ue ip {}".format(ue_ip))
        return ue_ip

    def detach(self):
        self._ue_proxy.unlock_screen()
        self._ue_proxy.disable_mobile_data()
        self._ue_proxy.enable_airplane()
